insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x6-c2$qa$, $qa$pemweb-x6$qa$, $qa$checkpoint$qa$, $qa$Sebutkan tiga keadaan (state) sebuah Promise!$qa$, $qa$["start → process → end", "pending → fulfilled / rejected", "open → half-open → closed", "init → loading → done"]$qa$::jsonb, 1, $qa$Promise berada di pending, lalu menjadi fulfilled (berhasil) atau rejected (gagal).$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
