insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x6-b3$qa$, $qa$pemweb-x6$qa$, $qa$battle$qa$, $qa$Keunggulan utama async/await dibanding promise berantai (.then) adalah...$qa$, $qa$["Berjalan lebih cepat secara komputasi", "Kode asinkron terbaca seperti kode sinkron sehingga mudah dipahami", "Tidak membutuhkan fungsi sama sekali", "Hanya bisa dipakai di browser lama"]$qa$::jsonb, 1, $qa$Async/await adalah syntactic sugar di atas Promise yang menghilangkan callback hell dan keterbacaan.$qa$, 3) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
